// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstTimestamp, uint256 secondTimestamp) public {
        // Ensure timestamps are non-decreasing and strictly increasing
        vm.assume(firstTimestamp >= 1); // avoid underflow in reference
        vm.assume(secondTimestamp > firstTimestamp);

        // First call - should succeed
        vm.warp(firstTimestamp);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        vm.assume(success1);

        // Second call with a later timestamp - should always succeed
        vm.warp(secondTimestamp);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // General rule: second call must succeed (revert when timestamps are reversed)
        assertTrue(success2);
    }
}

